L["Class"] = "Klasse"
L["Role"] = "Rolle"
L["Name"] = "Name"
L["Ascending"] = "Aufsteigend"
L["Descending"] = "Absteigend"
L["Choose how group members are ordered on these frames."] = "Legt fest, in welcher Reihenfolge Gruppenmitglieder auf diesen Rahmen angeordnet werden."
L["Reverse the order group members are listed in."] = "Kehrt die Reihenfolge um, in der Gruppenmitglieder aufgelistet werden."
L["Show player in party"] = "Spieler in Gruppen anzeigen"
L["Show player in raid"] = "Spieler in Schlachtzügen anzeigen"
L["Include your own frame among these frames in a party that is not a raid."] = "Zeigt dein eigenes Fenster unter diesen Fenstern, wenn du in einer Gruppe bist, die kein Schlachtzug ist."
L["Include your own frame among these frames in a raid. Arenas and battlegrounds count as raids."] = "Zeigt dein eigenes Fenster unter diesen Fenstern, wenn du in einem Schlachtzug bist. Arenen und Schlachtfelder zählen als Schlachtzug."

L["Auto-Hide"] = "Automatisch ausblenden"
L["Hide the minimap automatically"] = "Minikarte automatisch ausblenden"
L["Hide the minimap while you are in the content selected below, and bring it back as soon as you leave it."] = "Blendet die Minikarte aus, solange du dich in den unten gewählten Inhalten befindest, und zeigt sie wieder an, sobald du sie verlässt."
L["Arenas"] = "Arenen"
L["Battlegrounds"] = "Schlachtfelder"
L["Dungeons"] = "Dungeons"
L["Raid instances"] = "Schlachtzugsinstanzen"
L["Hide the minimap while you are in an arena match."] = "Blendet die Minikarte aus, solange du dich in einem Arenakampf befindest."
L["Hide the minimap while you are in a battleground."] = "Blendet die Minikarte aus, solange du dich auf einem Schlachtfeld befindest."
L["Hide the minimap while you are in a dungeon."] = "Blendet die Minikarte aus, solange du dich in einem Dungeon befindest."
L["Hide the minimap while you are in a raid instance."] = "Blendet die Minikarte aus, solange du dich in einer Schlachtzugsinstanz befindest."
L["Show empty buttons"] = "Leere Schaltflächen anzeigen"
L["Show the empty slots on your action bars as blank buttons. Turn this off to show only the buttons you have actually put something on. Empty buttons fade with the rest of the bar when bar fading is enabled."] = "Zeigt die leeren Plätze deiner Aktionsleisten als leere Schaltflächen an. Schalte dies aus, um nur die Schaltflächen zu sehen, auf die du tatsächlich etwas gelegt hast. Leere Schaltflächen blenden zusammen mit dem Rest der Leiste aus, wenn das Ausblenden der Leiste aktiviert ist."

L["Dismount Button"] = "Absteige-Schaltfläche"
L["The dismount button appears while you are mounted, in a vehicle or in control of another creature, and clicking it puts you back on your own feet. It normally sits at the upper left of the minimap ring and follows the minimap around."] = "Die Absteige-Schaltfläche erscheint, während du reitest, in einem Fahrzeug sitzt oder eine andere Kreatur steuerst, und ein Klick darauf bringt dich zurück auf eigene Füße. Normalerweise sitzt sie oben links am Ring der Minikarte und folgt der Minikarte."
L["Use a custom position"] = "Eigene Position verwenden"
L["Detach the dismount button from the minimap and put it anywhere on screen. Type /lock to drag it into place. A button with a position of its own no longer belongs to the minimap, so it also stays visible when the minimap hides itself."] = "Löst die Absteige-Schaltfläche von der Minikarte und platziert sie an einer beliebigen Stelle des Bildschirms. Tippe /lock, um sie an ihren Platz zu ziehen. Eine Schaltfläche mit eigener Position gehört nicht mehr zur Minikarte und bleibt daher auch sichtbar, wenn sich die Minikarte selbst ausblendet."
L["Type /lock to bring up the frame mover, then drag the dismount button where you want it. Mouse wheel over it there to resize it."] = "Tippe /lock, um den Rahmenschieber aufzurufen, und zieh die Absteige-Schaltfläche dorthin, wo du sie haben willst. Mit dem Mausrad darüber änderst du ihre Größe."

L["%s is restyling the game menu too, and the two styles clash. Which game menu do you want to keep?"] = "%s gestaltet das Spielmenü ebenfalls um, und die beiden Stile vertragen sich nicht. Welches Spielmenü möchtest du behalten?"
L["Picking AzeriteUI or Blizzard turns %s off for this character. The interface reloads to apply your choice."] = "Wählst du AzeriteUI oder Blizzard, wird %s für diesen Charakter deaktiviert. Die Benutzeroberfläche wird neu geladen, um deine Wahl zu übernehmen."
L["Blizzard"] = "Blizzard"
L["Decide Later"] = "Später entscheiden"
L["Both"] = "Beide"
L["AzeriteUI and %s"] = "AzeriteUI und %s"
L["Picking AzeriteUI turns %s off for this character. Both keeps the two running. The interface reloads to apply your choice."] = "Wählst du AzeriteUI, wird %s für diesen Charakter deaktiviert. Mit Beide laufen beide weiter. Die Benutzeroberfläche wird neu geladen, um deine Wahl zu übernehmen."
L["Game menu style"] = "Stil des Spielmenüs"
L["AzeriteUI restyles the game menu you open with Escape. If another addon restyles it too, AzeriteUI asks which one you want to keep when you open the menu."] = "AzeriteUI gestaltet das Spielmenü um, das du mit Escape öffnest. Gestaltet ein anderes Addon es ebenfalls um, fragt AzeriteUI beim Öffnen des Menüs, welches du behalten möchtest."
L["Choose which addon styles the game menu. Changing this reloads the interface."] = "Wähle, welches Addon das Spielmenü gestaltet. Eine Änderung lädt die Benutzeroberfläche neu."
L["This turns %s off for this character and reloads the interface."] = "Dadurch wird %s für diesen Charakter deaktiviert und die Benutzeroberfläche neu geladen."
L["The game menu style changes when the interface reloads."] = "Der Stil des Spielmenüs ändert sich, sobald die Benutzeroberfläche neu geladen wird."

