L["Control Types"] = "Steuerelementtypen"
L["The control types no setting in this addon uses yet, so that they can be tested at all. Visible only in Development Mode; nothing here changes the interface."] = "Die Steuerelementtypen, die noch keine Einstellung dieses Addons nutzt, damit sie sich überhaupt testen lassen. Nur im Entwicklermodus sichtbar; nichts hier verändert die Oberfläche."
L["Color"] = "Farbe"
L["Color with alpha"] = "Farbe mit Deckkraft"
L["Opens the game's own color picker. The swatch shows the color as it is used on the left and opaque on the right."] = "Öffnet die Farbauswahl des Spiels. Das Farbfeld zeigt links die Farbe wie verwendet und rechts deckend."
L["Color without alpha"] = "Farbe ohne Deckkraft"
L["The same control with no opacity to set, which is the more common shape."] = "Dasselbe Steuerelement ohne einstellbare Deckkraft, die häufigere Form."
L["Keybinding"] = "Tastenbelegung"
