L["Click, then press the combination you want. Escape clears it. This records the binding as text and binds nothing; a real setting decides what to do with it."] = "Klicken, dann die gewünschte Kombination drücken. Escape löscht sie. Die Belegung wird nur als Text gespeichert und nichts wird gebunden; eine echte Einstellung entscheidet, was damit geschieht."
L["Multiselect"] = "Mehrfachauswahl"
L["Several choices"] = "Mehrere Optionen"
L["One setting with a value per key, drawn as a toggle each. Each row reads and writes its own key."] = "Eine Einstellung mit einem Wert pro Schlüssel, jeweils als Schalter dargestellt. Jede Zeile liest und schreibt ihren eigenen Schlüssel."
L["Alpha"] = "Alpha"
L["Beta"] = "Beta"
L["Gamma"] = "Gamma"
L["Color %.2f %.2f %.2f at %.0f%%. Keybinding %s. Chosen %s"] = "Farbe %.2f %.2f %.2f bei %.0f%%. Tastenbelegung %s. Gewählt %s"
L["nothing"] = "nichts"
L["%s: expected %s"] = "%s: erwartet %s"
