L["Quick Start"] = "Schnellstart"
L["The settings that change the most, gathered from every page. Each one is still on its own page as well."] = "Die Einstellungen, die am meisten verändern, von allen Seiten gesammelt. Jede steht weiterhin auch auf ihrer eigenen Seite."
L["Changed"] = "Geändert"
L["Nothing here differs from its default."] = "Hier weicht nichts vom Standard ab."
L["Show only the settings that differ from their defaults."] = "Nur die Einstellungen anzeigen, die vom Standard abweichen."
L["Back to the page you were on."] = "Zurück zur vorherigen Seite."
L["Blizzard's raid bar only appears in a party or raid."] = "Blizzards Schlachtzugsleiste erscheint nur in Gruppe oder Schlachtzug."
L["Applies to cast names on the target frame and nameplates."] = "Gilt für Zaubernamen am Zielfenster und an Namensplaketten."
L["Applies to auras on target, group and arena frames and nameplates."] = "Für Auren an Ziel-, Gruppen- und Arenafenstern sowie Namensplaketten."
L["Applies to health bars on unit frames and nameplates."] = "Gilt für Gesundheitsleisten an Einheitenfenstern und Namensplaketten."
