L["Changes how key presses reach the bars, not how they look."] = "Ändert, wie Tastendrücke die Leisten erreichen, nicht ihr Aussehen."
L["Applies to every element Explorer Mode fades."] = "Gilt für alle Elemente, die der Erkundungsmodus ausblendet."
L["No friendly nameplate is visible to preview."] = "Keine freundliche Namensplakette für die Vorschau sichtbar."
L["No friendly NPC nameplate is visible to preview."] = "Keine freundliche NPC-Namensplakette für die Vorschau sichtbar."
L["No enemy nameplate is visible to preview."] = "Keine feindliche Namensplakette für die Vorschau sichtbar."
