L["Target an enemy to preview this."] = "Wähle einen Gegner als Ziel für die Vorschau."
L["Target a friendly player to preview this."] = "Wähle einen freundlichen Spieler als Ziel für die Vorschau."
L["Changes how far away nameplates appear."] = "Ändert, auf welche Entfernung Namensplaketten erscheinen."
L["Applies to tooltips. Hover over something to see one."] = "Gilt für Tooltips. Fahre über etwas, um einen zu sehen."
L["Open the world map to preview this."] = "Öffne die Weltkarte für die Vorschau."
L["Open the game menu to preview this."] = "Öffne das Spielmenü für die Vorschau."
L["Open your bags to preview this."] = "Öffne deine Taschen für die Vorschau."
