L["Enemy Castbars"] = "Feindliche Zauberbalken"
L["Show who the cast is aimed at"] = "Ziel des Zaubers anzeigen"
L["The name of the cast's target under the spell name, in their class color. The game decides which casts show a name."] = "Der Name des Zauberziels unter dem Zaubernamen, in seiner Klassenfarbe. Das Spiel entscheidet, bei welchen Zaubern ein Name erscheint."
