L["Masque's switch is under Action Bars"] = "Der Schalter für Masque ist unter Aktionsleisten"
L["Friendly"] = "Freundlich"
L["Quest Marks"] = "Questmarkierungen"
L["Health Text"] = "Gesundheitstext"
L["Combo Points"] = "Combopunkte"
L["Only for Your Target"] = "Nur für dein Ziel"
L["Which day and night indicator the minimap shows: AzeriteUI's on the edge of the map, which you can drag around the ring and right-click to set its distance, Blizzard's own on the minimap cluster, or none."] = "Welche Tag-und-Nacht-Anzeige die Minikarte zeigt: die von AzeriteUI am Rand der Karte, die du um den Ring ziehen und per Rechtsklick im Abstand einstellen kannst, Blizzards eigene am Minikartenbereich oder keine."
L["AzeriteUI's"] = "Von AzeriteUI"
L["Blizzard's"] = "Von Blizzard"
L["Show the top center widgets"] = "Widgets oben in der Mitte anzeigen"
L["Always, or only while you have no target."] = "Immer oder nur, solange du kein Ziel hast."
L["Always"] = "Immer"
L["Hide with a target"] = "Mit Ziel ausblenden"
L["Style tooltips"] = "Tooltips gestalten"
